import"./chunk-2NFLSA4Y.js";var o={relativity:{theory:{concept:"[[Special relativity is Einstein's theory (1905) of space and time for observers moving at constant velocity relative to one another, in inertial frames of reference.]] It rests on two postulates: the laws of physics are the same in every inertial frame, and the speed of light in a vacuum, c, is the same for all observers. It follows that time intervals and lengths depend on the frame: a moving clock runs slow, \u0394\u03C4 = \u0394t / \u03B3, and a moving rod is shorter along its motion, L = L\u2080 / \u03B3, where \u03B3 = 1/\u221A(1 \u2212 v\xB2/c\xB2). No frame is preferred, and the effects become large only at speeds close to c."},section:{clocks:{title:"Time dilation",text:"The time recorded by a clock moving with the object is its proper time. [[In the laboratory frame it accumulates \u0394\u03C4 = \u0394t/\u03B3 during laboratory time \u0394t.]] This comparison is frame-dependent: each inertial observer can regard the other's clock as moving. A reunion comparison requires specifying acceleration and the complete paths."},rods:{title:"Length contraction",text:"A rod has rest length L\u2080 in its own frame. [[The laboratory measures L = L\u2080/\u03B3 along the direction of motion.]] Its endpoints must be measured simultaneously in the laboratory frame; a photograph is not the same measurement."},limit:{title:"Why can't a massive object reach c?",text:"As the speed approaches c, \u03B3 grows without bound. Accelerating an object with mass to c would require unbounded energy. Light in vacuum travels at c, but a photon is not a resting clock or rod in this model."},scope:{title:"Special and general relativity",text:"This experiment uses special relativity: uniform motion without gravity. General relativity describes gravity through curved spacetime. Explore the separate Spacetime Curvature 3D analogy, then see a quantitative general-relativistic result in the Black Holes topic."},evidence:{title:"Measured every day",text:"Time dilation is not only theory. Muons made by cosmic rays high in the atmosphere live only 2.2 \xB5s at rest \u2014 too short to reach the ground \u2014 yet many do, because seen from the Earth their clocks run slowly. CERN's Large Hadron Collider drives protons to more than 0.99999999 c, where \u03B3 is about 7 000. GPS satellites move at about 3.9 km/s, which slows their clocks by about 7 \xB5s a day; every satnav receiver corrects for it. In 2010 atomic clocks became precise enough to see time dilation at the speed of a cyclist."},try:{title:"Try it",text:"Set the speed to zero, then to 0.6c and 0.9c. Run both clocks for the same laboratory interval and compare their readings and the two rods. Which quantities change, and which stay the same?"}},formula:{beta:"Speed as a fraction of the speed of light",gamma:"Lorentz factor for an inertial observer",time:"Proper time accumulated by the moving clock in the laboratory frame",length:"Laboratory length of a rod parallel to its motion"},variable:{speed:"Speed fraction v/c",gamma:"Lorentz factor",labTime:"Laboratory time interval",properTime:"Moving clock's proper-time interval",restLength:"Rod length in its rest frame"},assumption:{inertial:"Both observers move inertially in flat spacetime; there is no acceleration or gravity.",simultaneity:"The clocks are set to zero together in the laboratory frame. Rod endpoints are compared at one laboratory time. The displayed clocks remain side by side schematically; no physical reunion is implied.",scale:"Travel distances near light speed are enormous over seconds. The clock and rod drawing is not to scale and does not depict how an object would appear in a photograph.",animation:"The bouncing markers are deliberately slowed clock diagrams. Their drawn motion is not the actual speed of light."},param:{speedFraction:"Speed (fraction of c)",restLength:"Rod rest length",duration:"Laboratory duration",timeStep:"Simulation timestep"},hint:{speedFraction:"0.6 means the moving frame travels at 60% of vacuum light speed relative to the laboratory.",restLength:"Length measured in the rod's own rest frame."},measure:{restClockTime:"Laboratory clock",movingClockTime:"Moving clock",contractedLength:"Rod length in laboratory",lorentzFactor:"Lorentz factor",clockRate:"Moving clock rate in laboratory",clockDifference:"Clock reading difference"},visual:{motionArrow:"Direction of motion"},view:{restClock:"Laboratory clock",movingClock:"Moving clock",restRod:"Rod at rest",movingRod:"Moving rod",notToScale:"Diagram not to scale"},graph:{clocks:"Clock readings over laboratory time"},challenge:{rest:{title:"At rest",description:"Make the two clocks run at the same rate.",hint:"Set the relative speed to zero."},shrink:{title:"Shorter rod",description:"Make the moving rod at least 20% shorter in the laboratory frame.",hint:"Raise the relative speed to at least 0.6c."},double:{title:"Double the factor",description:"Reach a Lorentz factor of at least 2.",hint:"Try a speed near 0.9c."},difference:{title:"Three seconds apart",description:"Finish a run with at least 3 seconds between the clock readings.",hint:"Use a high speed and a long laboratory duration."}}}},a={sim:o};export{a as default,o as sim};
